import type { ToolCallResult } from '../types';

interface AgentCallbacks {
  onTextChunk: (text: string) => void;
  onToolCall: (toolCallId: string, sql: string) => void;
  onToolResult: (result: ToolCallResult) => void;
  onDone: (sessionId: string | null) => void;
  onError: (error: string) => void;
}

export async function runAgentLoop(
  message: string,
  sessionId: string | null,
  callbacks: AgentCallbacks,
  signal?: AbortSignal,
): Promise<void> {
  try {
    const response = await fetch('/api/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ message, session_id: sessionId }),
      signal,
    });

    if (!response.ok) {
      const errorText = await response.text();
      callbacks.onError(`Server error: ${errorText}`);
      return;
    }

    const reader = response.body?.getReader();
    if (!reader) {
      callbacks.onError('No response stream');
      return;
    }

    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() ?? '';

      let eventType = '';
      for (const line of lines) {
        if (line.startsWith('event: ')) {
          eventType = line.slice(7).trim();
        } else if (line.startsWith('data: ')) {
          const data = line.slice(6);
          try {
            const parsed = JSON.parse(data);
            handleSSEEvent(eventType, parsed, callbacks);
          } catch {
            // Skip malformed JSON
          }
          eventType = '';
        }
      }
    }
  } catch (e: unknown) {
    if (signal?.aborted) return;
    const msg = e instanceof Error ? e.message : 'Connection failed';
    callbacks.onError(msg);
  }
}

function handleSSEEvent(
  eventType: string,
  data: Record<string, unknown>,
  callbacks: AgentCallbacks,
) {
  switch (eventType) {
    case 'thinking':
    case 'answer':
      callbacks.onTextChunk(data.text as string);
      break;
    case 'tool_call':
      callbacks.onToolCall(data.id as string, data.sql as string);
      break;
    case 'tool_result': {
      const result: ToolCallResult = {
        toolCallId: (data.id as string) ?? '',
        sql: (data.sql as string) ?? '',
        columns: (data.columns as string[]) ?? [],
        rows: (data.rows as Record<string, unknown>[]) ?? [],
        rowCount: (data.rowCount as number) ?? 0,
        error: (data.error as string) ?? undefined,
        rawContent: (data.content as string) ?? undefined,
      };
      callbacks.onToolResult(result);
      break;
    }
    case 'done':
      callbacks.onDone((data.session_id as string) ?? null);
      break;
    case 'error':
      callbacks.onError((data.message as string) ?? 'Unknown error');
      break;
  }
}

"""Internal client implementation."""

from collections.abc import AsyncIterable, AsyncIterator
from dataclasses import asdict, replace
from typing import Any

from ..types import (
    ClaudeAgentOptions,
    HookEvent,
    HookMatcher,
    Message,
)
from .message_parser import parse_message
from .query import Query
from .transport import Transport
from .transport.subprocess_cli import SubprocessCLITransport


class InternalClient:
    """Internal client implementation."""

    def __init__(self) -> None:
        """Initialize the internal client."""

    def _convert_hooks_to_internal_format(
        self, hooks: dict[HookEvent, list[HookMatcher]]
    ) -> dict[str, list[dict[str, Any]]]:
        """Convert HookMatcher format to internal Query format."""
        internal_hooks: dict[str, list[dict[str, Any]]] = {}
        for event, matchers in hooks.items():
            internal_hooks[event] = []
            for matcher in matchers:
                # Convert HookMatcher to internal dict format
                internal_matcher: dict[str, Any] = {
                    "matcher": matcher.matcher if hasattr(matcher, "matcher") else None,
                    "hooks": matcher.hooks if hasattr(matcher, "hooks") else [],
                }
                if hasattr(matcher, "timeout") and matcher.timeout is not None:
                    internal_matcher["timeout"] = matcher.timeout
                internal_hooks[event].append(internal_matcher)
        return internal_hooks

    async def process_query(
        self,
        prompt: str | AsyncIterable[dict[str, Any]],
        options: ClaudeAgentOptions,
        transport: Transport | None = None,
    ) -> AsyncIterator[Message]:
        """Process a query through transport and Query."""

        # Validate and configure permission settings (matching TypeScript SDK logic)
        configured_options = options
        if options.can_use_tool:
            # canUseTool callback requires streaming mode (AsyncIterable prompt)
            if isinstance(prompt, str):
                raise ValueError(
                    "can_use_tool callback requires streaming mode. "
                    "Please provide prompt as an AsyncIterable instead of a string."
                )

            # canUseTool and permission_prompt_tool_name are mutually exclusive
            if options.permission_prompt_tool_name:
                raise ValueError(
                    "can_use_tool callback cannot be used with permission_prompt_tool_name. "
                    "Please use one or the other."
                )

            # Automatically set permission_prompt_tool_name to "stdio" for control protocol
            configured_options = replace(options, permission_prompt_tool_name="stdio")

        # Use provided transport or create subprocess transport
        if transport is not None:
            chosen_transport = transport
        else:
            chosen_transport = SubprocessCLITransport(
                prompt=prompt,
                options=configured_options,
            )

        # Connect transport
        await chosen_transport.connect()

        # Extract SDK MCP servers from configured options
        sdk_mcp_servers = {}
        if configured_options.mcp_servers and isinstance(
            configured_options.mcp_servers, dict
        ):
            for name, config in configured_options.mcp_servers.items():
                if isinstance(config, dict) and config.get("type") == "sdk":
                    sdk_mcp_servers[name] = config["instance"]  # type: ignore[typeddict-item]

        # Convert agents to dict format for initialize request
        agents_dict = None
        if configured_options.agents:
            agents_dict = {
                name: {k: v for k, v in asdict(agent_def).items() if v is not None}
                for name, agent_def in configured_options.agents.items()
            }

        # Create Query to handle control protocol
        # Always use streaming mode internally (matching TypeScript SDK)
        # This ensures agents are always sent via initialize request
        query = Query(
            transport=chosen_transport,
            is_streaming_mode=True,  # Always streaming internally
            can_use_tool=configured_options.can_use_tool,
            hooks=self._convert_hooks_to_internal_format(configured_options.hooks)
            if configured_options.hooks
            else None,
            sdk_mcp_servers=sdk_mcp_servers,
            agents=agents_dict,
        )

        try:
            # Start reading messages
            await query.start()

            # Always initialize to send agents via stdin (matching TypeScript SDK)
            await query.initialize()

            # Handle prompt input
            if isinstance(prompt, str):
                # For string prompts, write user message to stdin after initialize
                # (matching TypeScript SDK behavior)
                import json

                user_message = {
                    "type": "user",
                    "session_id": "",
                    "message": {"role": "user", "content": prompt},
                    "parent_tool_use_id": None,
                }
                await chosen_transport.write(json.dumps(user_message) + "\n")
                await chosen_transport.end_input()
            elif isinstance(prompt, AsyncIterable) and query._tg:
                # Stream input in background for async iterables
                query._tg.start_soon(query.stream_input, prompt)

            # Yield parsed messages
            async for data in query.receive_messages():
                yield parse_message(data)

        finally:
            await query.close()

import type { ToolCallResult } from '../types';
import './InlineQueryResult.css';

const MAX_DISPLAY_ROWS = 20;

export function InlineQueryResult({ result }: { result: ToolCallResult }) {
  if (result.error) {
    return (
      <div className="inline-query inline-query--error">
        <div className="inline-query__sql">
          <code>{result.sql}</code>
        </div>
        <div className="inline-query__error">{result.error}</div>
      </div>
    );
  }

  const displayRows = result.rows.slice(0, MAX_DISPLAY_ROWS);
  const hasStructuredData = result.columns.length > 0;

  return (
    <div className="inline-query">
      {result.sql && (
        <div className="inline-query__sql">
          <code>{result.sql}</code>
        </div>
      )}
      {hasStructuredData ? (
        <>
          <div className="inline-query__table-wrapper">
            <table className="inline-query__table">
              <thead>
                <tr>
                  {result.columns.map((col) => (
                    <th key={col}>{col}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {displayRows.map((row, i) => (
                  <tr key={i}>
                    {result.columns.map((col) => (
                      <td key={col}>{String(row[col] ?? '')}</td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          <div className="inline-query__meta">
            {result.rowCount} row{result.rowCount !== 1 ? 's' : ''}
            {result.rowCount > MAX_DISPLAY_ROWS && ` (showing ${MAX_DISPLAY_ROWS})`}
          </div>
        </>
      ) : result.rawContent ? (
        <div className="inline-query__raw">
          <pre>{result.rawContent}</pre>
        </div>
      ) : result.sql ? (
        <div className="inline-query__meta">Executing...</div>
      ) : null}
    </div>
  );
}

