CLAUDECODE= poetry run python -c "
import asyncio, json
from app.agent import stream_chat
from app.database import db

# Load sample data first
db.conn.execute('CREATE TABLE test AS SELECT 1 as id, 42 as value')

async def test():
    events = []
    async for event in stream_chat('what tables do I have? show me the data'):
        for line in event.strip().split('\n'):
            if line.startswith('event:'):
                event_type = line.split(': ', 1)[1]
            elif line.startswith('data:'):
                data = json.loads(line.split(': ', 1)[1])
                text = data.get('text', '')
                if event_type in ('thinking', 'answer'):
                    events.append(f'{event_type}: {text[:60]}')
                elif event_type == 'tool_call':
                    events.append(f'tool_call: sql={data.get(\"sql\", \"\")[:60]}')
                elif event_type == 'tool_result':
                    events.append(f'tool_result: cols={data.get(\"columns\")}, rows={len(data.get(\"rows\", []))}')
                else:
                    events.append(f'{event_type}: {json.dumps(data)[:80]}')
        if 'event: done' in event or 'event: error' in event:
            break

    print('=== DISTINCT EVENT TYPES IN ORDER ===')
    last_type = None
    for e in events:
        t = e.split(':')[0]
        if t != last_type:
            if t in ('tool_call', 'tool_result'):
                print(f'  -> {e}')
            else:
                print(f'  -> {t}')
            last_type = t

asyncio.run(test())
" 2>&1

