.inline-query {
  margin: 8px 0;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  overflow: hidden;
  font-size: 12px;
}

.inline-query--error {
  border-color: #fca5a5;
}

.inline-query--bash {
  border-color: #c4b5fd;
}

.inline-query--generic {
  border-color: #93c5fd;
}

/* Tool label */
.inline-query__label {
  padding: 3px 10px;
  font-size: 11px;
  font-weight: 600;
  border-bottom: 1px solid #e5e7eb;
}

.inline-query__label--sql {
  color: #065f46;
  background: #ecfdf5;
  border-bottom-color: #a7f3d0;
}

.inline-query__label--bash {
  color: #6d28d9;
  background: #ede9fe;
  border-bottom-color: #c4b5fd;
}

.inline-query__label--generic {
  color: #1e40af;
  background: #eff6ff;
  border-bottom-color: #93c5fd;
}

