.inline-query__output {
  padding: 8px 10px;
  overflow-x: auto;
  max-height: 300px;
  overflow-y: auto;
  background: #f9fafb;
}

.inline-query__output pre {
  margin: 0;
  font-size: 12px;
  color: #374151;
  white-space: pre-wrap;
  word-break: break-word;
}

.inline-query__raw {
  padding: 8px 10px;
  overflow-x: auto;
}

.inline-query__raw pre {
  margin: 0;
  font-size: 12px;
  color: #4b5563;
  white-space: pre-wrap;
  word-break: break-word;
}

